mapper.select:
/* Archive02Mapper.selectArchiveTypeList */
SELECT
    D.BAIM_VAL_D_CD     AS archiveTypeCd
  , D.BAIM_VAL_D_NM     AS archiveTypeNm
  , D.SORT_IDX          AS sortIdx
FROM TB_BAIM_VAL_D D
WHERE D.CMPNY_CD = #{gvCmpnyCd}
  AND D.BAIM_VAL_CD = #{baimValCd}
  AND D.USE_YN = 'Y'
ORDER BY D.SORT_IDX ASC, D.BAIM_VAL_D_CD ASC

/* Archive02Mapper.countArchiveTypeValid */
SELECT
    COUNT(1)
FROM TB_BAIM_VAL_D D
WHERE D.CMPNY_CD = #{cmpnyCd}
  AND D.BAIM_VAL_CD = #{baimValCd}
  AND D.BAIM_VAL_D_CD = #{archiveTypeCd}

    AND D.USE_YN = 'Y'

mapper.update:
/* Archive02Mapper.updateArchive */
UPDATE TB_NOTICE
SET
    ARCHIVE_TYPE_CD = #{archiveTypeCd}
  , TITLE           = #{title}
  , CONTENT         = #{content}
  , UPDATE_NO       = #{gvUserCd}
  , UPDATE_DATE     = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND NOTICE_ID = #{noticeId}
  AND NOTICE_TYPE = 'ARCHIVE'
  AND DEL_YN = 'N'

