/* Archive02Mapper.updateArchiveDelYn */
UPDATE TB_NOTICE
SET
    DEL_YN      = 'Y'
  , UPDATE_NO   = #{gvUserCd}
  , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND NOTICE_ID = #{noticeId}
  AND NOTICE_TYPE = 'ARCHIVE'
  AND DEL_YN = 'N'

