/* Archive02Mapper.selectArchivePwdHash */
SELECT
    A.EDIT_PWD
FROM TB_NOTICE A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.NOTICE_ID = #{noticeId}
  AND A.NOTICE_TYPE = 'ARCHIVE'
  AND A.DEL_YN = 'N'

/* Archive02Mapper.countArchiveVisible */
SELECT
    COUNT(1)
FROM TB_NOTICE N
WHERE N.CMPNY_CD = #{gvCmpnyCd}
  AND N.NOTICE_ID = #{noticeId}
  AND N.NOTICE_TYPE = 'ARCHIVE'
  AND N.DEL_YN = 'N'

/* Archive02Mapper.countNodeAdminAnySite */
SELECT
    COUNT(1)
FROM TB_SITE_NODE
WHERE CMPNY_CD = #{cmpnyCd}
  AND ( MAIN_ADMIN_CD = #{userCd} OR SUB_ADMIN_CD = #{userCd} )
